// The fund's name, filled in when the template is added.
const FUND = {{fund}};
// The goal, and the month to reach it by: the end of the next June.
const GOAL = 2000;
const BY_MONTH = 6;
const INK = '#121a2e';
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October',
  'November', 'December'];
const MINT = { light: '#effbe6', dark: '#183a3a' };
const WORDS = { light: INK, dark: '#eef4ff' };
const LEAF = { light: '#2f8a4c', dark: '#7fd6a0' };
const PERCENT = { light: '#1f7a45', dark: '#7fd6a0' };
const TRACK = { light: '#121a2e1F', dark: '#FFFFFF29' };
const KEY = { light: INK, dark: '#7fd6a0' };
const KEY_WORDS = { light: '#effbe6', dark: '#122929' };
const JAR = 'M8 3h8v3H8zM7 6h10l1 3v10a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2V9z M9 14h6';
// Fuji under a red sun, with a torii gate. Its snow is cut out of the mountain, and a white peak in the backdrop
// shows through the cut in full color, so the snow still reads in tinted and clear mode.
const SNOW = 'M41 41 L50 30 Q55 25 60 30 L69 41 L62 38 L55 44 L48 38Z';
const MOUNTAIN = 'M6 80 L50 30 Q55 25 60 30 L104 80Z M48 38 L55 44 L62 38 L69 41 L60 30 Q55 25 50 30 L41 41Z';
const TORII = 'M12 56h26v3.6H12z M14 62h22v2.8H14z M16 56h3.2v24H16z M31 56h3.2v24H31z';

function fuji(u, under) {
  const part = (d, fill, extra) => Object.assign({ type: 'path', d, viewBox: [0, 0, 130, 84], fill }, extra);
  return { type: 'zstack', padding: { top: 30 * u, trailing: 16 * u },
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topTrailing' },
    children: [
      { type: 'zstack', frame: { width: 122 * u, height: 122 * u * 84 / 130 }, children: under
        ? [part(SNOW, '#FFFFFF')]
        : [
          part('M77 24a15 15 0 1 0 30 0a15 15 0 1 0 -30 0z', '#e5484d'),
          part(MOUNTAIN, { light: '#2b3a67', dark: '#5e78a8' }),
          part(TORII, '#e5484d'),
          part('M0 80h130', null, { stroke: { color: '#9cc98a', width: 4 * 122 * u / 130 } }),
        ] },
    ] };
}

// The key's fill sits twice: solid in the backdrop, which tinted and clear mode remove, and faint in the tree.
// So in full color it reads as one solid key, and in tinted mode its words still show on the faint one.
function key(u, ghost) {
  return { type: 'zstack', padding: { trailing: 15 * u, bottom: 12 * u },
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomTrailing' },
    children: [
      { type: ghost ? 'zstack' : 'button', action: ghost ? null : 'add', children: [
        { type: 'zstack', padding: { vertical: 7 * u, horizontal: 11 * u },
          background: { type: 'rect', cornerRadius: 10 * u, fill: ghost ? KEY : { light: '#121a2e40', dark: '#7fd6a040' } },
          children: [
            { type: 'text', value: '+$50', size: 12.5 * u, weight: 'bold', color: KEY_WORDS, opacity: ghost ? 0 : 1 },
          ] } ] },
    ] };
}

function money(n) {
  return '$' + String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

// What to save each week to reach the goal by the end of the next BY_MONTH.
function plan(saved, today) {
  if (saved >= GOAL) return 'of ' + money(GOAL) + ', and you made it';
  const year = Number(today.slice(0, 4)) + (Number(today.slice(5, 7)) > BY_MONTH ? 1 : 0);
  const end = new Date(Date.UTC(year, BY_MONTH, 0));
  const weeks = Math.max(1, Math.ceil((end - new Date(today)) / (7 * 86400000)));
  return 'of ' + money(GOAL) + ', ' + money(Math.ceil((GOAL - saved) / weeks)) + ' a week to make it by '
    + MONTHS[BY_MONTH - 1];
}

function render(ctx) {
  // Sizes are in the prototype's units: a widget is 170 of them tall. Bricolage's line is 1.2 times its size, so
  // the gaps around the amount are 0.1 of its size shorter than the prototype's.
  const u = ctx.height / 170;
  const d = ctx.data;
  const wide = ctx.family === 'medium';
  const share = Math.min(1, d.saved / GOAL);
  const column = (ctx.width - 32 * u) * (wide ? 0.54 : 1);
  const track = wide ? ctx.width * 0.54 : ctx.width - 110 * u;

  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: { type: 'zstack', frame: { maxWidth: 'infinity', maxHeight: 'infinity' }, background: MINT,
      children: [wide && fuji(u, true), key(u, true)] },
    children: [
      wide && fuji(u, false),
      { type: 'vstack', align: 'leading', spacing: 0, padding: { top: 15 * u, leading: 16 * u, trailing: 16 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
        children: [
          { type: 'hstack', spacing: 5 * u, frame: { height: 16 * u }, children: [
            { type: 'path', d: JAR, viewBox: [0, 0, 24, 24], frame: { width: 15 * u, height: 15 * u },
              stroke: { color: LEAF, width: 2.4 * 15 * u / 24 } },
            { type: 'text', value: FUND, size: 13 * u, weight: 'bold', color: LEAF, lineLimit: 1, minScale: 0.4 },
            wide && { type: 'spacer', minLength: 0 },
            wide && { type: 'text', value: Math.round(share * 100) + '%', size: 13 * u, weight: 'heavy', color: PERCENT,
              lineLimit: 1 },
          ] },
          { type: 'text', value: money(d.saved), fontName: 'Bricolage Grotesque Display', size: 36 * u,
            kerning: -1.08 * u, color: WORDS, accent: true, lineLimit: 1, minScale: 0.5, padding: { top: 4.4 * u },
            frame: { maxWidth: column, alignment: 'leading' } },
          { type: 'text', value: wide ? plan(d.saved, ctx.today.date) : Math.round(share * 100) + '% of ' + money(GOAL), size: 12.5 * u, weight: 'semibold',
            color: WORDS, opacity: 0.8, lineLimit: 2, minScale: 0.8, padding: { top: 1.4 * u },
            frame: { maxWidth: column, alignment: 'leading' } },
        ] },
      { type: 'zstack', align: 'leading', padding: { leading: 16 * u, bottom: 16 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomLeading' },
        children: [
          { type: 'zstack', align: 'leading', frame: { width: track, height: 12 * u },
            children: [
              { type: 'rect', cornerRadius: 6 * u, fill: TRACK },
              share > 0 && { type: 'rect', cornerRadius: 6 * u, fill: '#2fbf80', accent: true,
                frame: { width: track * share } },
            ] },
        ] },
      d.last && d.last.minutesAgo < 10 && { type: 'zstack', padding: { trailing: 80 * u, bottom: 8 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomTrailing' },
        children: [
          { type: 'button', action: 'undo', rowId: d.last.id, children: [
            { type: 'symbol', name: 'arrow.uturn.backward', size: 12, weight: 'bold', color: WORDS,
              frame: { width: 30, height: 30 }, background: { light: '#121a2e14', dark: '#FFFFFF1F' },
              clip: 'circle' } ] },
        ] },
      key(u, false),
    ],
  };
}
